with unpacked as (select id, coupon_codes, ship_to, array_max(transform(items, item -> item.price)) as max_item_price, ship_to.country as ship_country, coalesce(attributes['utm_source'], 'direct') as utm_source_or_default from carts) select id, coupon_codes, ship_to, max_item_price, ship_country, utm_source_or_default, row_number() over (partition by ship_country order by max_item_price, id) row_seq, row_number() over (order by max_item_price desc, id) row_seq_2 from unpacked;
